def olculeri_satira_cevir(apps, schema_editor):
    """Eski siparişlerin tek ölçüsü bir ölçü satırı olur; işi hiç açılmamış açık siparişlere iş açılır; sevk tarihi."""
    Siparis = apps.get_model("uretim", "Siparis")
    SiparisKalemi = apps.get_model("uretim", "SiparisKalemi")
    UretimLotu = apps.get_model("uretim", "UretimLotu")
    bugun = timezone.localdate()
    Siparis.objects.filter(durum="sevk").update(sevk_tarihi=bugun)
    bas = f"IS-{bugun.year}-"
    son = UretimLotu.objects.filter(lot_no__startswith=bas).order_by("-lot_no").values_list("lot_no", flat=True).first()
    sira = int(son.rsplit("-", 1)[1]) if son else 0
    for sp in Siparis.objects.filter(en_cm__isnull=False, boy_cm__isnull=False):
        kalem = SiparisKalemi.objects.create(siparis=sp, sira=1, en_cm=sp.en_cm, boy_cm=sp.boy_cm, adet=sp.adet or 1)
        # Var olan işler bu satıra bağlanır (sipariş düzenlenince aynı ölçüye ikinci iş açılmasın).
        UretimLotu.objects.filter(siparis=sp).update(kalem=kalem)
        if sp.durum == "acik" and not UretimLotu.objects.filter(siparis=sp).exists():
            sira += 1
            m2 = (kalem.en_cm * kalem.boy_cm * kalem.adet / 10000).quantize(Decimal("0.01"))
            UretimLotu.objects.create(lot_no=f"{bas}{sira:04d}", siparis=sp, kalem=kalem, baslangic_kg=0,
                                      baslangic_m2=m2, mevcut_kg=0, mevcut_m2=m2)


